static int cobs_frame_tester(const uint8_t *buf, size_t len, void *user_data)
{
	struct net_buf *dst = user_data;

	if (buf == NULL) {
		/*
		 * When COBS_FLAG_TRAILING_DELIMITER is used, the cobs_decoder_write
		 * calls this callback with buf == NULL when it encounters the delimiter.
		 * Additionally, cobs_encoder_close also signals end of frame with buf == NULL,
		 * which propagates through the decoder. This results in two buf == NULL calls
