		 * If dst->len is 0 and the expected decoded_len is not 0, it means the buffer
		 * was already reset by the first call, so this is a redundant call.
		 * If the expected decoded_len is 0 (empty frame), dst->len will also be 0,
		 * so we must process it.
		 */
		const struct cobs_test_item *test = &cobs_dataset[frame_test_idx];
		if (dst->len == 0 && test->decoded_len != 0) {
			/* Redundant NULL signal for a non-empty frame, ignore. */
			return 0;
		}

		zassert_equal(test->decoded_len, dst->len,
			      "Decoded length does not match expected for %s", test->name);
		zassert_mem_equal(test->decoded, dst->data, test->decoded_len,
				  "Decoded data does not match expected for %s", test->name);

		net_buf_reset(dst);
		frame_test_idx++;
		return 0;
	}

	if (net_buf_tailroom(dst) < len) {
		return -ENOMEM;
	}

	(void)net_buf_add_mem(dst, buf, len);

	return 0;
}
